data.query:
query Query($where: WorkOrderWhereInput, $orderBy: [WorkOrderOrderByInput!], $first: Int, $after: String) {
  workOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
   edges {
      node {
        id
        workOrderProcesses {
          edges {
            node {
              id
              workOrderProcessBoms {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
        workOrderDistributions {
               total
                 edges {
                  node {
                    id
                   coDistributions {
                    total
                    edges {
                      node {
                        id
                        number
                       }
                      }
                    }

         distributionGroup {
                    id
              }
            }
          }
        }
      }
    }
  }
}

query Query($where: WorkOrderProcessDistributionGroupWhereInput, $orderBy: [WorkOrderProcessDistributionGroupOrderByInput!], $first: Int, $after: String) {
  workOrderProcessDistributionGroup(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
       node {
        id
        distributions {
         total
        }
      }
    }
  }
}

